#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a visible, non-secret value into $KEY.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: owner-only live-provider activation and rollback.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {
  ACTION="${1:-}"
  case "$ACTION" in
    up) TOTAL_STAGES=7 ;;
    down) TOTAL_STAGES=4 ;;
    *)
      printf 'Usage: %s {up|down}\n' "${0##*/}" >&2
      exit 2
      ;;
  esac

  banner "Finance Assistant live providers $ACTION"

  PROJECT_ID="comfforts-369117"
  REGION="us-west1"
  REPOSITORY="hankgalt/ai_finance_assitant"
  GITHUB_ENVIRONMENT="staging"
  STAGING_BUCKET="comfforts-369117-aifa-tf-staging"
  BACKEND_SERVICE="aifa-staging-backend"
  FRONTEND_SERVICE="aifa-staging-frontend"
  EDGE_BACKEND_SERVICES=("aifa-staging-backend-edge" "aifa-staging-frontend-edge")
  OWNER_EMAIL="vtalwar.w@comfforts.com"
  ARTIFACT_REGISTRY_ROOT="us-west1-docker.pkg.dev/comfforts-369117/aifa-containers"
  TARGET_URL="https://apps.comfforts.com/finance_assistant"
  HEALTH_URL="$TARGET_URL/api/health/ready"
  SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
  REPO_ROOT=$(cd "$SCRIPT_DIR/../../.." && pwd)
  FOUNDATION_ROOT="$REPO_ROOT/infrastructure/terraform/environments/staging"
  WORKLOAD_ROOT="$REPO_ROOT/infrastructure/terraform/environments/staging-workloads"
  CONTRACT="$REPO_ROOT/contracts/providers/live-mode.v1.json"
  EVIDENCE_DIR="$REPO_ROOT/backend/artifacts/providers/deployment"
  TEMP_DIR=$(mktemp -d "${TMPDIR:-/tmp}/aifa-live-providers.XXXXXX")
  FOUNDATION_PLAN="$TEMP_DIR/foundation.tfplan"
  WORKLOAD_PLAN="$TEMP_DIR/workloads.tfplan"
  SERVICE_DESCRIPTION="$TEMP_DIR/backend.json"
  SERVICE_IAM="$TEMP_DIR/backend-iam.json"
  trap 'rm -f "$FOUNDATION_PLAN" "$WORKLOAD_PLAN" "$SERVICE_DESCRIPTION" "$SERVICE_IAM"; rmdir "$TEMP_DIR" 2>/dev/null || true' EXIT

  # Read one required non-secret GitHub environment variable without printing it.
  github_environment_variable() {
    gh variable get "$1" --repo "$REPOSITORY" --env "$GITHUB_ENVIRONMENT"
  }

  # Resolve the newest enabled numeric version without ever reading its payload.
  latest_enabled_secret_version() {
    local secret_id="$1" version
    version=$(gcloud secrets versions list "$secret_id" \
      --project="$PROJECT_ID" --format=json | jq -r '
        [.[] | select(.state == "ENABLED")] |
        sort_by(.createTime) | last | .name // empty
      ')
    version="${version##*/}"
    [[ "$version" =~ ^[1-9][0-9]*$ ]] || return 1
    printf '%s' "$version"
  }

  # Capture or reuse a secret version through the console; payloads never enter this process.
  select_secret_version() {
    local provider="$1" secret_id="$2" version=""
    version=$(latest_enabled_secret_version "$secret_id" || true)
    if [[ "$version" =~ ^[1-9][0-9]*$ ]] && \
      confirm "Reuse enabled $provider secret version $version?"; then
      printf -v "$3" '%s' "$version"
      return
    fi
    open_url "https://console.cloud.google.com/security/secret-manager/secret/$secret_id/versions?project=$PROJECT_ID"
    step "Choose New version, paste the $provider API key, and enable that version."
    pause "Return here after the enabled version exists. Press Enter to continue."
    version=$(latest_enabled_secret_version "$secret_id" || true)
    [[ "$version" =~ ^[1-9][0-9]*$ ]] || {
      warn "no enabled numeric version exists for $secret_id"
      exit 1
    }
    printf -v "$3" '%s' "$version"
  }

  # Export the already-approved deployment selectors shared by both Terraform states.
  export_common_terraform_variables() {
    export TF_VAR_backend_image
    export TF_VAR_frontend_image
    export TF_VAR_qdrant_secret_version
    export TF_VAR_iap_audience
    TF_VAR_backend_image=$(github_environment_variable GCP_BACKEND_IMAGE)
    TF_VAR_frontend_image=$(github_environment_variable GCP_FRONTEND_IMAGE)
    TF_VAR_qdrant_secret_version=$(github_environment_variable GCP_QDRANT_SECRET_VERSION)
    TF_VAR_iap_audience=$(github_environment_variable GCP_IAP_AUDIENCE)
  }

  # Initialize the two independently owned staging state roots.
  initialize_terraform_states() {
    terraform -chdir="$FOUNDATION_ROOT" init -reconfigure \
      -backend-config="bucket=$STAGING_BUCKET" \
      -backend-config="prefix=foundation"
    terraform -chdir="$WORKLOAD_ROOT" init -reconfigure \
      -backend-config="bucket=$STAGING_BUCKET" \
      -backend-config="prefix=workloads"
  }

  # Update one environment-scoped, non-secret GitHub deployment selector.
  set_environment_variable() {
    gh variable set "$1" --repo "$REPOSITORY" --env "$GITHUB_ENVIRONMENT" --body "$2"
  }

  # Re-read the deployed backend and IAM boundary into execution-scoped files.
  refresh_backend_readback() {
    gcloud run services describe "$BACKEND_SERVICE" \
      --project="$PROJECT_ID" --region="$REGION" --format=json > "$SERVICE_DESCRIPTION"
    gcloud run services get-iam-policy "$BACKEND_SERVICE" \
      --project="$PROJECT_ID" --region="$REGION" --format=json > "$SERVICE_IAM"
  }

  # ── Stage 1: read-only repository, identity, and runtime preflight ───────
  stage "Verify merged main, local tools, identity, and runtime"
  say "This stage reads configuration only and accepts no credential payload."
  for tool in gcloud terraform git gh jq curl; do
    command -v "$tool" >/dev/null 2>&1 || { warn "$tool is not available on PATH"; exit 1; }
  done
  [[ "$(gcloud auth list --filter=status:ACTIVE --format='value(account)')" == "$OWNER_EMAIL" ]] || {
    warn "the active gcloud account must be $OWNER_EMAIL"
    exit 1
  }
  [[ "$(gcloud config get-value project 2>/dev/null)" == "$PROJECT_ID" ]] || {
    warn "the active gcloud project must be $PROJECT_ID"
    exit 1
  }
  gh auth status >/dev/null
  [[ "$(git -C "$REPO_ROOT" branch --show-current)" == "main" ]] || {
    warn "switch to main before changing live-provider mode"
    exit 1
  }
  [[ -z "$(git -C "$REPO_ROOT" status --porcelain)" ]] || {
    warn "the repository must be clean before changing live-provider mode"
    exit 1
  }
  git -C "$REPO_ROOT" rev-parse origin/main >/dev/null 2>&1 || {
    warn "origin/main is unavailable; fetch before continuing"
    exit 1
  }
  [[ "$(git -C "$REPO_ROOT" rev-parse HEAD)" == "$(git -C "$REPO_ROOT" rev-parse origin/main)" ]] || {
    warn "local main does not match the fetched origin/main"
    exit 1
  }
  jq -e '.status == "repository_implemented_live_run_pending" or .status == "qualified"' \
    "$CONTRACT" >/dev/null
  gcloud sql instances describe aifa-staging-postgres \
    --project="$PROJECT_ID" --format='value(state)' | grep -qx RUNNABLE
  for service in "$BACKEND_SERVICE" "$FRONTEND_SERVICE"; do
    gcloud run services describe "$service" \
      --project="$PROJECT_ID" --region="$REGION" \
      --format='value(status.conditions[0].status)' >/dev/null
  done
  export_common_terraform_variables
  if [[ "$ACTION" == "up" ]]; then
    REVISION=$(git -C "$REPO_ROOT" rev-parse HEAD)
    BACKEND_TAG_DIGEST=$(gcloud artifacts docker images describe \
      "$ARTIFACT_REGISTRY_ROOT/finance-assistant-backend:$REVISION" \
      --project="$PROJECT_ID" --format='value(image_summary.digest)' 2>/dev/null || true)
    FRONTEND_TAG_DIGEST=$(gcloud artifacts docker images describe \
      "$ARTIFACT_REGISTRY_ROOT/finance-assistant-frontend:$REVISION" \
      --project="$PROJECT_ID" --format='value(image_summary.digest)' 2>/dev/null || true)
    [[ "$TF_VAR_backend_image" == "$ARTIFACT_REGISTRY_ROOT/finance-assistant-backend@$BACKEND_TAG_DIGEST" ]] || {
      warn "GCP_BACKEND_IMAGE is not the mirrored merged-main backend image for $REVISION"
      warn "run make mirror-merged-main-images and make set-deployment-image-variables first"
      exit 1
    }
    [[ "$TF_VAR_frontend_image" == "$ARTIFACT_REGISTRY_ROOT/finance-assistant-frontend@$FRONTEND_TAG_DIGEST" ]] || {
      warn "GCP_FRONTEND_IMAGE is not the mirrored merged-main frontend image for $REVISION"
      warn "run make mirror-merged-main-images and make set-deployment-image-variables first"
      exit 1
    }
  fi
  initialize_terraform_states
  say "Verified clean merged main and the active private-demo runtime."

  if [[ "$ACTION" == "down" ]]; then
    # ── Stage 2: fail closed to credential-free before removing secrets ───
    stage "Review the credential-free workload rollback"
    export TF_VAR_provider_mode="credential_free"
    export TF_VAR_openai_secret_version="0"
    export TF_VAR_massive_secret_version="0"
    export TF_VAR_tavily_secret_version="0"
    terraform -chdir="$WORKLOAD_ROOT" plan -lock-timeout=5m -out="$WORKLOAD_PLAN"
    terraform -chdir="$WORKLOAD_ROOT" show -no-color "$WORKLOAD_PLAN"
    say "Type exactly: DISABLE LIVE PROVIDERS"
    printf '  > '
    read -r confirmation
    [[ "$confirmation" == "DISABLE LIVE PROVIDERS" ]] || {
      warn "confirmation did not match; nothing was changed"
      exit 1
    }
    terraform -chdir="$WORKLOAD_ROOT" apply "$WORKLOAD_PLAN"

    # ── Stage 3: remove now-unused provider secret metadata and payloads ───
    stage "Review removal of disposable provider secrets"
    warn "Deleting each Secret Manager resource permanently removes all of its provider-key versions."
    export TF_VAR_live_provider_secrets_enabled="false"
    terraform -chdir="$FOUNDATION_ROOT" plan -lock-timeout=5m -out="$FOUNDATION_PLAN"
    terraform -chdir="$FOUNDATION_ROOT" show -no-color "$FOUNDATION_PLAN"
    confirm "Apply this reviewed provider-secret removal after credential-free cutover?" || exit 1
    terraform -chdir="$FOUNDATION_ROOT" apply "$FOUNDATION_PLAN"

    # ── Stage 4: reconcile GitHub selectors and verify the safe default ────
    stage "Reconcile deployment variables and verify rollback"
    set_environment_variable GCP_LIVE_PROVIDER_MODE credential_free
    set_environment_variable GCP_OPENAI_SECRET_VERSION 0
    set_environment_variable GCP_MASSIVE_SECRET_VERSION 0
    set_environment_variable GCP_TAVILY_SECRET_VERSION 0
    refresh_backend_readback
    jq -e '
      def value($name):
        .spec.template.spec.containers[] | select(.name == "backend") |
        .env[] | select(.name == $name) | .value;
      value("AIFA_PROVIDER_MODE") == "credential_free" and
      value("AIFA_MODEL_MODE") == "credential_free" and
      ([.spec.template.spec.containers[] | select(.name == "backend") | .env[].name] |
        all(. != "AIFA_OPENAI_API_KEY" and . != "AIFA_MASSIVE_API_KEY" and . != "AIFA_TAVILY_API_KEY"))
    ' "$SERVICE_DESCRIPTION" >/dev/null
    say "Credential-free mode is restored and live-provider secret references are absent."
    finish
    return
  fi

  # ── Stage 2: provider-account rights and spend controls ─────────────────
  stage "Confirm account rights and provider-side limits"
  open_url "https://platform.openai.com/settings/organization/limits"
  step "Select the API project used by this app and verify its hard monthly usage limit is USD 20."
  ask OPENAI_USAGE_TIER "OpenAI API usage tier shown for this account/project:"
  [[ -n "$OPENAI_USAGE_TIER" && "$OPENAI_USAGE_TIER" != *$'\n'* ]] || {
    warn "an OpenAI usage tier label is required for the evidence record"
    exit 1
  }
  confirm "Is the USD 20 hard monthly OpenAI limit active for the selected API project?" || exit 1
  open_url "https://app.tavily.com/home"
  step "Verify this is the Researcher plan and that pay-as-you-go is disabled."
  confirm "Is Tavily Researcher active with pay-as-you-go disabled?" || exit 1
  open_url "https://massive.com/dashboard/keys"
  step "Verify the key belongs to Stocks Basic and will be used only by the subscribing owner."
  confirm "Is Massive Stocks Basic approved for this owner-only personal demonstration?" || exit 1

  # ── Stage 3: Terraform-owned Secret Manager metadata and IAM ────────────
  stage "Create provider secret metadata and runtime access"
  say "Terraform creates metadata and least-privilege IAM only; it never receives a key payload."
  export TF_VAR_live_provider_secrets_enabled="true"
  terraform -chdir="$FOUNDATION_ROOT" plan -lock-timeout=5m -out="$FOUNDATION_PLAN"
  terraform -chdir="$FOUNDATION_ROOT" show -no-color "$FOUNDATION_PLAN"
  confirm "Apply only this reviewed three-secret metadata and IAM plan?" || exit 1
  terraform -chdir="$FOUNDATION_ROOT" apply "$FOUNDATION_PLAN"

  # ── Stage 4: human-only key entry in Secret Manager ─────────────────────
  stage "Add provider keys directly to Secret Manager"
  say "This wizard observes only enabled numeric version identifiers."
  select_secret_version OpenAI aifa-staging-openai-api-key OPENAI_SECRET_VERSION
  select_secret_version Massive aifa-staging-massive-api-key MASSIVE_SECRET_VERSION
  select_secret_version Tavily aifa-staging-tavily-api-key TAVILY_SECRET_VERSION
  note "Selected numeric versions: OpenAI $OPENAI_SECRET_VERSION, Massive $MASSIVE_SECRET_VERSION, Tavily $TAVILY_SECRET_VERSION."

  # ── Stage 5: atomic live workload cutover ───────────────────────────────
  stage "Review and apply the owner-only live workload"
  export TF_VAR_provider_mode="live"
  export TF_VAR_openai_secret_version="$OPENAI_SECRET_VERSION"
  export TF_VAR_massive_secret_version="$MASSIVE_SECRET_VERSION"
  export TF_VAR_tavily_secret_version="$TAVILY_SECRET_VERSION"
  terraform -chdir="$WORKLOAD_ROOT" plan -lock-timeout=5m -out="$WORKLOAD_PLAN"
  terraform -chdir="$WORKLOAD_ROOT" show -no-color "$WORKLOAD_PLAN"
  confirm "Apply only this reviewed live-provider workload plan?" || exit 1
  terraform -chdir="$WORKLOAD_ROOT" apply "$WORKLOAD_PLAN"

  # ── Stage 6: machine readback plus owner browser qualification ──────────
  stage "Qualify configuration, private boundary, and live journeys"
  refresh_backend_readback
  jq -e \
    --arg openai "$OPENAI_SECRET_VERSION" \
    --arg massive "$MASSIVE_SECRET_VERSION" \
    --arg tavily "$TAVILY_SECRET_VERSION" '
      def env($name):
        .spec.template.spec.containers[] | select(.name == "backend") |
        .env[] | select(.name == $name);
      def secret_version($name):
        env($name).valueFrom.secretKeyRef |
        (.version // .key | tostring);
      env("AIFA_PROVIDER_MODE").value == "live" and
      env("AIFA_MODEL_MODE").value == "openai_live" and
      env("AIFA_MARKET_DATA_PROVIDER").value == "massive" and
      env("AIFA_IAP_VIEWER_EMAILS").value == "[]" and
      env("AIFA_PROVIDER_CACHE_ENABLED").value == "false" and
      env("AIFA_MODEL_REQUEST_BUDGET").value == "10" and
      env("AIFA_MARKET_PROVIDER_REQUESTS_PER_MINUTE").value == "5" and
      env("AIFA_NEWS_PROVIDER_REQUEST_BUDGET").value == "5" and
      secret_version("AIFA_OPENAI_API_KEY") == $openai and
      secret_version("AIFA_MASSIVE_API_KEY") == $massive and
      secret_version("AIFA_TAVILY_API_KEY") == $tavily and
      .metadata.annotations["run.googleapis.com/ingress"] == "internal-and-cloud-load-balancing" and
      .metadata.annotations["run.googleapis.com/default-url-disabled"] == "true" and
      any(.status.conditions[]?; .type == "Ready" and .status == "True")
    ' "$SERVICE_DESCRIPTION" >/dev/null
  jq -e 'all(.bindings[]?.members[]?; . != "allUsers" and . != "allAuthenticatedUsers")' \
    "$SERVICE_IAM" >/dev/null
  for edge_service in "${EDGE_BACKEND_SERVICES[@]}"; do
    EDGE_ID=$(gcloud compute backend-services describe "$edge_service" \
      --project="$PROJECT_ID" --global --format='value(id)')
    gcloud iap web get-iam-policy \
      --project="$PROJECT_ID" \
      --resource-type=backend-services \
      --service="$EDGE_ID" \
      --format=json | jq -e \
      --arg owner "user:$OWNER_EMAIL" '
        [.bindings[]? |
          select(.role == "roles/iap.httpsResourceAccessor") |
          .members[]?] == [$owner] and
        all(.bindings[]?.members[]?; . != "allUsers" and . != "allAuthenticatedUsers")
      ' >/dev/null
  done
  DIRECT_URL=$(jq -r '.status.url // empty' "$SERVICE_DESCRIPTION")
  if [[ -n "$DIRECT_URL" ]] && curl --silent --show-error --fail --max-time 15 \
    "$DIRECT_URL/api/health/live" >/dev/null 2>&1; then
    warn "the backend accepted anonymous direct-origin traffic"
    exit 1
  fi
  open_url "$HEALTH_URL"
  step "Complete IAP sign-in as $OWNER_EMAIL and verify readiness reports status ok."
  pause "Return after readiness is ok. Press Enter to continue."
  confirm "Did the protected readiness endpoint report model, market, news, storage, and knowledge ready?" || exit 1
  open_url "$TARGET_URL"
  step "Run a Finance/Tax question and verify Inspector records measured OpenAI token usage."
  step "Run an owner-only market request and verify Massive live provenance and end-of-day labeling."
  step "Run a public finance-news request and verify Tavily links/attribution; do not enter portfolio or tax context in the news query."
  confirm "Did all three live journeys pass without exposing a provider response, raw prompt, or credential in logs/evidence?" || exit 1

  # ── Stage 7: GitHub plan selectors and secret-free evidence ─────────────
  stage "Reconcile deployment variables and write qualification evidence"
  set_environment_variable GCP_LIVE_PROVIDER_MODE live
  set_environment_variable GCP_OPENAI_SECRET_VERSION "$OPENAI_SECRET_VERSION"
  set_environment_variable GCP_MASSIVE_SECRET_VERSION "$MASSIVE_SECRET_VERSION"
  set_environment_variable GCP_TAVILY_SECRET_VERSION "$TAVILY_SECRET_VERSION"
  [[ "$(github_environment_variable GCP_LIVE_PROVIDER_MODE)" == "live" ]]
  [[ "$(github_environment_variable GCP_OPENAI_SECRET_VERSION)" == "$OPENAI_SECRET_VERSION" ]]
  [[ "$(github_environment_variable GCP_MASSIVE_SECRET_VERSION)" == "$MASSIVE_SECRET_VERSION" ]]
  [[ "$(github_environment_variable GCP_TAVILY_SECRET_VERSION)" == "$TAVILY_SECRET_VERSION" ]]
  GENERATED_AT=$(date -u +'%Y-%m-%dT%H:%M:%SZ')
  EVIDENCE_FILE="$EVIDENCE_DIR/live-mode-$REVISION.v1.json"
  mkdir -p "$EVIDENCE_DIR"
  jq -n \
    --arg revision "$REVISION" \
    --arg generated_at "$GENERATED_AT" \
    --arg usage_tier "$OPENAI_USAGE_TIER" \
    --arg openai_version "$OPENAI_SECRET_VERSION" \
    --arg massive_version "$MASSIVE_SECRET_VERSION" \
    --arg tavily_version "$TAVILY_SECRET_VERSION" '
      {
        schema_version: "1",
        status: "qualified",
        qualification_revision: $revision,
        generated_at: $generated_at,
        target: "https://apps.comfforts.com/finance_assistant",
        audience: {
          owner: "vtalwar.w@comfforts.com",
          viewer_admission: "disabled",
          direct_origin: "denied"
        },
        selection: {
          provider_mode: "live",
          model_mode: "openai_live",
          model: "gpt-6.1-sol",
          market_provider: "massive",
          news_provider: "tavily"
        },
        account_rights: {
          openai_usage_tier: $usage_tier,
          openai_monthly_usd_hard_limit: 20,
          openai_real_application_data_approved: true,
          massive_plan: "Stocks Basic personal owner-only",
          massive_viewer_display_allowed: false,
          tavily_plan: "Researcher",
          tavily_pay_as_you_go_enabled: false
        },
        secret_versions: {
          openai: $openai_version,
          massive: $massive_version,
          tavily: $tavily_version
        },
        qualification: {
          deployed_configuration_readback: "passed",
          readiness: "passed_owner_observation",
          openai_measured_usage: "passed_owner_observation",
          massive_live_provenance: "passed_owner_observation",
          tavily_attribution: "passed_owner_observation",
          direct_origin_denial: "passed"
        },
        limitations: [
          "Owner-only private demonstration; viewer admission and viewer live-provider access remain disabled.",
          "The USD 20 OpenAI ceiling is an owner-attested provider-account control, not an application cost calculator.",
          "No provider payload, prompt, response, or user financial value is committed as evidence."
        ],
        secret_payloads_recorded: false,
        raw_provider_outputs_recorded: false
      }
    ' > "$EVIDENCE_FILE"
  say "Wrote secret-free qualification evidence: ${EVIDENCE_FILE#"$REPO_ROOT/"}"
  say "Review and commit that generated evidence on a dedicated evidence branch."
  finish
}

run_wizard "$@"; exit
